// The Logs page host (#3646, epic #3604) — renders the Logs workspace FROM THE GRAPH. The page and its
// tab bodies are sourced from the components graph (the authored `logspage` node + siblings, seeded from
// `data/components/app/**`), not bundled files. It registers the feature's injected platform surface (the
// agentProfiles / consoleModel / auditRows logic the graph page imports), then mounts `logspage` through
// the runtime loader. Mirrors FleetGraphHost / AutomationsGraphHost.
//
// This host WAS SecurityGraphHost. The Security workspace dissolved into Logs: Profiles, Assignments and
// Flow were deleted outright, and Activity — the one surface with a real audit feed behind it — is the
// first tab of the unified Logs screen. Sessions, Waiting, Skills, Hooks, Cost and Streams follow as
// their own slices, all reading the `bsc logs` engine (#1607) rather than growing a second log reader.
//
// `pageOverride` (a torn-off single tab, DetachedWindow) forwards to the graph component as a prop —
// GraphComponent spreads props onto the loaded component, and the graph `LogsWorkspace` reads it.
//
// The stylesheet is loaded by the ENTRY's `@/**/*.css` glob (the-entry-owns-stylesheet-loading), not by a
// module import here: the runtime loader cannot resolve a CSS side-effect import, so a graph-hosted page
// must never depend on one.
import { GraphComponent } from "@/shared/lib/runtime/GraphComponent";
import { GraphPageFallback } from "@/shared/lib/runtime/GraphPageFallback";
import { registerLogsPlatform } from "@/features/logs/graphPlatform";

// Register at module load — before the workspace ever renders — so the injected modules are in the registry
// when the graph page's compiled `require()` runs. Idempotent.
registerLogsPlatform();

export function LogsGraphHost({ pageOverride }: { pageOverride?: string } = {}) {
  // Fallback offers a one-click re-seed (#3648) when the source isn't in the library yet.
  return (
    <GraphComponent
      id="logspage"
      props={pageOverride ? { pageOverride } : undefined}
      fallback={<GraphPageFallback page="Logs" icon="▤" />}
    />
  );
}
